-- Release 2026-10-18 · bước 3/3: sản phẩm
--
-- Cùng cách làm với bước 2: sinh từ database local, khoá ngoại nối bằng khoá
-- tự nhiên (người tạo theo email, thành viên theo slug, danh mục theo slug),
-- bản ghi giữ nguyên id vì `files` và đường dẫn ảnh trỏ vào id đó.
--
-- CHẠY SAU 01-schema.sql: product_media ở đây có hai cột device và is_hero.
--
--   psql -d <db> -v ON_ERROR_STOP=1 -f 03-products.sql

BEGIN;

DO $guard$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM users WHERE email = 'trungld@zakutek.com') THEN
    RAISE EXCEPTION 'Thieu tai khoan trungld@zakutek.com';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM members WHERE slug = 'nhat') THEN
    RAISE EXCEPTION 'Thieu thanh vien slug=nhat — san pham gan vao nguoi nay';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
     WHERE table_name = 'product_media' AND column_name = 'is_hero'
  ) THEN
    RAISE EXCEPTION 'Chua chay 01-schema.sql: product_media thieu cot is_hero';
  END IF;
END
$guard$;

INSERT INTO products (
  id, slug, name, summary, body_html, body_json, cover_path, status, lifecycle,
  version, released_at, audience, platforms, tech_stack, highlights,
  is_featured, sort_order, product_url, demo_url, demo_access,
  demo_instructions, seo_title, seo_description, seo_keywords, canonical_url,
  seo_noindex, seo_nofollow, og_title, og_description, og_path, published_at,
  published_snapshot, created_by, created_at, updated_at)
VALUES (
  '2bb5c174-fba2-416d-90ef-79b6c8113482', 'cofyn', 'Cofyn', 'Cofyn là sổ chung cho nhóm khởi nghiệp: quản lý ý tưởng, biểu quyết, quỹ và dự án trong một không gian, giúp nhóm nhỏ phối hợp rõ ràng ngay cả khi làm ngoài giờ.',
  '<h2>Cofyn – Sổ chung cho nhóm khởi nghiệp</h2><p>Cofyn là ứng dụng web tiếng Việt giúp nhóm nhỏ quản lý ý tưởng, biểu quyết, quỹ chung và dự án trong một không gian. Sản phẩm phù hợp với những đội cùng xây sản phẩm ngoài giờ, cần theo dõi quyết định, tiền và tiến độ mà không phải tìm lại nhiều nhóm chat hay bảng tính.</p><h2>Từ ý tưởng đến dự án, mọi người cùng nắm thông tin</h2><p>Một đề xuất được đăng trong chat rất dễ trôi; khoản góp quỹ và chi phí lại nằm trong một file riêng. Cofyn kết nối các công việc này để nhóm có thể nhìn lại điều đã thống nhất, ai đang phụ trách và khoản tiền phục vụ dự án nào.</p><h2>Tính năng chính của Cofyn</h2><h3>Ý tưởng và biểu quyết</h3><p>Đăng ý tưởng kèm vấn đề, hướng thực hiện và chi phí dự kiến. Thành viên bỏ phiếu Thuận hoặc Không; ý tưởng được xét theo đa số để nhóm có kết luận rõ ràng trước khi triển khai.</p><h3>Quỹ chung minh bạch</h3><p>Ghi nhận các khoản đóng góp và chi tiêu, người thực hiện, mục đích và dự án liên quan. Nhóm theo dõi số dư và thống kê thu chi từ cùng một nơi thay vì đối chiếu nhiều bảng tính.</p><h3>Dự án và tiến độ</h3><p>Theo dõi người phụ trách, ngân sách, chi phí thực tế và dòng thời gian cập nhật của từng dự án. Những thành viên làm việc khác lịch vẫn có thể xem tiến độ và tiếp nối công việc.</p><h3>Tài nguyên và wiki nội bộ</h3><p>Quản lý domain, hosting, VPS và tài khoản trả phí cùng người giữ, giá và thời hạn. Lưu quy trình, ghi chú và quyết định bằng Markdown trong wiki để cả nhóm cùng cập nhật và tra cứu.</p><h3>Poll, CofynAI và API</h3><p>Tạo bình chọn phương án trong ý tưởng. CofynAI hỗ trợ soạn poll, chấm điểm ý tưởng và trả lời bình luận. API dùng token riêng theo nhóm để đọc ý tưởng, dự án, thu chi và ghi cập nhật từ công cụ khác. Các khả năng AI và API phụ thuộc gói sử dụng.</p><h3>Nhật ký và kho lưu trữ</h3><p>Theo dõi các thay đổi đã xảy ra; nội dung đã xóa được đưa vào Kho lưu trữ để có thể khôi phục hoặc xử lý tiếp khi cần.</p><h2>Cofyn phù hợp với ai?</h2><ul><li><p><strong>Nhóm co-founder từ 2–10 người:</strong> cùng xây sản phẩm và cần rõ ràng về đóng góp, chi phí và quyết định.</p></li><li><p><strong>Nhóm side project:</strong> làm ngoài giờ, ít thời gian họp, cần ghi chú và cập nhật tiến độ tập trung.</p></li><li><p><strong>Câu lạc bộ và đội dự án sinh viên:</strong> quản lý quỹ chung và đưa ra quyết định bằng biểu quyết.</p></li></ul><h2>Quy trình sử dụng</h2><ol><li><p><strong>Đề xuất ý tưởng:</strong> nêu vấn đề, cách làm và chi phí dự kiến.</p></li><li><p><strong>Cả nhóm biểu quyết:</strong> ghi nhận ý kiến để chốt hướng triển khai.</p></li><li><p><strong>Chuyển thành dự án:</strong> giữ mô tả, ngân sách và bổ sung người phụ trách.</p></li><li><p><strong>Triển khai và ghi chép:</strong> cập nhật tiến độ, thu chi, tài nguyên và tài liệu liên quan.</p></li></ol><h2>Trải nghiệm Cofyn trên web</h2><p>Cofyn hoạt động trên trình duyệt, có thể truy cập từ máy tính, iPad và điện thoại. Mỗi nhóm có không gian riêng; dữ liệu nhóm được chia sẻ cho thành viên trong nhóm, không phải một tài khoản chung với các sản phẩm Zukatek khác.</p><p>Theo thông tin công khai của Cofyn, giai đoạn pilot miễn phí và không yêu cầu thẻ. Gói Free phục vụ nhu cầu nhóm cơ bản; AI và API được giới thiệu trong gói Premium. Điều kiện tính năng và gói sử dụng có thể thay đổi, hãy xem thông tin hiện hành trên website sản phẩm.</p><p><a href="https://cofyn.app/users/sign-up" rel="nofollow">Tạo tài khoản Cofyn</a> để bắt đầu với nhóm của bạn, hoặc xem <a href="https://cofyn.app/docs" rel="nofollow">hướng dẫn sử dụng Cofyn</a> trước khi trải nghiệm.</p>',
