INSERT INTO published_docs (entity, locale, slug, entity_id, is_current, search_text, body, published_at, written_at)
VALUES ('product', 'en', 'cofyn', '2bb5c174-fba2-416d-90ef-79b6c8113482', true, 'Cofyn A shared workspace for startup teams to manage ideas, votes, a common fund and projects, keeping decisions and progress clear even when everyone works different hours.', E'{"id": "2bb5c174-fba2-416d-90ef-79b6c8113482", "seo": {"title": "Cofyn – Shared Funds and Projects for Startup Teams", "noindex": false, "og_path": null, "keywords": "Cofyn, quản lý quỹ nhóm, quản lý dự án nhóm, phần mềm cho startup, biểu quyết ý tưởng, wiki nội bộ", "nofollow": false, "og_title": "Cofyn – Ý tưởng, quỹ và dự án trong một chỗ", "description": "Manage team funds, ideas, voting, projects and an internal wiki with Cofyn. Built for small startup teams. Try the web app free during the pilot phase.", "canonical_url": null, "og_description": "Một cuốn sổ chung cho nhóm khởi nghiệp: cùng chốt ý tưởng, theo dõi quỹ, cập nhật dự án và lưu tri thức. Khám phá Cofyn trên web."}, "name": "Cofyn", "slug": "cofyn", "status": "published", "gallery": [{"id": "2c8b5e75-ea97-4b25-82ab-d1e450ab0473", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-5405e106-9cd6-410b-8a59-988b84cefcb1.webp", "kind": "image", "device": "desktop", "caption": null, "is_hero": false, "video_url": null, "created_at": "2026-10-18T16:36:52.173929+07:00", "sort_order": 0}, {"id": "ee184520-fd3a-4319-a15b-303b033b4b5f", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-7bf2261a-03d8-450e-b1e5-db3e21d741f5.webp", "kind": "image", "device": "tablet", "caption": null, "is_hero": false, "video_url": null, "created_at": "2026-10-18T16:36:52.208704+07:00", "sort_order": 1}, {"id": "e41a0960-f2f2-41b4-929e-2adfc1d54e7d", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-117a36d3-14f3-4ea2-8147-5b5dd22d8699.webp", "kind": "image", "device": "phone", "caption": null, "is_hero": false, "video_url": null, "created_at": "2026-10-18T16:36:52.490631+07:00", "sort_order": 2}, {"id": "9957