/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-d88e31e8-a457-4eb3-8017-391786ae9c65.webp", "kind": "image", "device": "desktop", "caption": null, "is_hero": false, "video_url": null, "created_at": "2026-10-18T16:36:53.788367+07:00", "sort_order": 9}, {"id": "6fb9c016-8755-4848-9558-bf135825f531", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-d511eab8-fd2c-4103-add5-a8853863c4dd.webp", "kind": "image", "device": "tablet", "caption": null, "is_hero": true, "video_url": null, "created_at": "2026-10-18T16:36:53.892797+07:00", "sort_order": 10}, {"id": "1067ec62-78d0-48c5-8348-e4f67e9561b4", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-a7ebb782-7e04-4cdb-8c9b-e0055f8b6914.webp", "kind": "image", "device": "phone", "caption": null, "is_hero": false, "video_url": null, "created_at": "2026-10-18T16:36:53.953031+07:00", "sort_order": 11}, {"id": "43cbb7c7-c434-4f14-bdf2-ecb51c287740", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-56518b0c-a2b1-4305-b7cf-5660039b0723.webp", "kind": "image", "device": "desktop", "caption": null, "is_hero": true, "video_url": null, "created_at": "2026-10-18T16:36:54.014697+07:00", "sort_order": 12}, {"id": "88327551-3a64-49df-be9b-89db31f80417", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-81e54c2a-2a18-470e-80db-aa6e8b6d1afa.webp", "kind": "image", "device": "tablet", "caption": null, "is_hero": false, "video_url": null, "created_at": "2026-10-18T16:36:54.071874+07:00", "sort_order": 13}, {"id": "cc269fa7-6748-4673-ae5d-1dce55cb9814", "url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/gallery-773bed79-44aa-4caa-aab8-7d26ca629dba.webp", "kind": "image", "device": "phone", "caption": null, "is_hero": true, "video_url": null, "created_at": "2026-10-18T16:36:54.128049+07:00", "sort_order": 14}], "members": [{"id": "7085ad1a-28b9-4a30-8c51-c3fadc16cb46", "role": null, "slug": "nhat", "full_name": "Nhật Nguyễn", "avatar_url": null, "sort_order": 0, "display_name": "Nat"}], "summary": "A shared workspace for startup teams to manage ideas, votes, a common fund and projects, keeping decisions and progress clear even when everyone works different hours.", "version": null, "audience": ["team"], "demo_url": "https://cofyn.app/users/sign-up", "body_html": "<h2>Cofyn – A shared ledger for startup teams</h2><p>Cofyn is a Vietnamese web application that brings ideas, team voting, a shared fund and projects into one workspace. It helps small teams working outside regular hours keep track of decisions, spending and progress.</p><h2>Keep ideas, money and progress together</h2><p>When proposals live in chat, expenses in a spreadsheet and updates in separate conversations, it becomes difficult to revisit a decision or understand a project''s costs. Cofyn connects these records so members can see what was agreed, who is responsible and how the team fund is used.</p><h2>Core features</h2><h3>Ideas and voting</h3><p>Share an idea with its problem, proposed approach and estimated cost. Members vote in favour or against it, with majority-based decisions before the team starts a project.</p><h3>A transparent team fund</h3><p>Record contributions and expenses with the person responsible, purpose and associated project. Review the balance and transaction summaries from one shared place.</p><h3>Projects and progress</h3><p>Track project owners, budgets, actual costs and a timeline of updates. Members working different schedules can follow what has changed and continue the work.</p><h3>Shared resources and an internal wiki</h3><p>Keep track of domains, hosting, VPS services and paid accounts, including owners, prices and renewal dates. Write procedures, decisions and notes in Markdown for the team to maintain and find later.</p><h3>Polls, CofynAI and API access</h3><p>Create polls inside ideas. CofynAI can help draft polls, assess ideas and reply to comments. A team-scoped API token allows supported tools to read ideas, projects and transactions or write progress updates. AI and API availability depends on the subscription plan.</p><h3>Activity history and archive</h3><p>Review recorded changes and recover deleted items from the archive when needed.</p><h2>Who is Cofyn for?</h2><ul><li><p><strong>Co-founder teams of 2–10 people</strong> building a product and keeping contributions, expenses and decisions clear.</p></li><li><p><strong>Side-project teams</strong> that work different hours and need concise updates instead of frequent meetings.</p></li><li><p><strong>Clubs and student project teams</strong> managing a small shared fund and voting on decisions.</p></li></ul><h2>From proposal to delivery</h2><ol><li><p>Describe an idea, the problem it solves and its estimated cost.</p></li><li><p>Let the team vote and agree on a direction.</p></li><li><p>Turn the approved idea into a project with an owner and budget.</p></li><li><p>Record progress, transactions, resources and project knowledge as the work continues.</p></li></ol><h2>Try Cofyn on the web</h2><p>Access Cofyn from a computer, iPad or phone browser. Each team has its own workspace for its members.</p><p>Cofyn''s public information describes a free pilot phase with no card required. The Free plan covers core team needs, while AI and API features are described under Premium. Check the product website for current plan availability and conditions.</p><p><a target=\\"_blank\\" rel=\\"noopener noreferrer nofollow\\" href=\\"https://cofyn.app/users/sign-up\\">Create a Cofyn account</a> to start your team, or read the <a target=\\"_blank\\" rel=\\"noopener noreferrer nofollow\\" href=\\"https://cofyn.app/docs\\">Cofyn user guide</a> first.</p>", "body_json": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2, "textAlign": null}, "content": [{"text": "Cofyn – Sổ chung cho nhóm khởi nghiệp", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Cofyn là ứng dụng web tiếng Việt giúp nhóm nhỏ quản lý ý tưởng, biểu quyết, quỹ chung và dự án trong một không gian. Sản phẩm phù hợp với những đội cùng xây sản phẩm ngoài giờ, cần theo dõi quyết định, tiền và tiến độ mà không phải tìm lại nhiều nhóm chat hay bảng tính.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2, "textAlign": null}, "content": [{"text": "Từ ý tưởng đến dự án, mọi người cùng nắm thông tin", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Một đề xuất được đăng trong chat rất dễ trôi; khoản góp quỹ và chi phí lại nằm trong một file riêng. Cofyn kết nối các công việc này để nhóm có thể nhìn lại điều đã thống nhất, ai đang phụ trách và khoản tiền phục vụ dự án nào.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2, "textAlign": null}, "content": [{"text": "Tính năng chính của Cofyn", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3, "textAlign": null}, "content": [{"text": "Ý tưởng và biểu quyết", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Đăng ý tưởng kèm vấn đề, hướng thực hiện và chi phí dự kiến. Thành viên bỏ phiếu Thuận hoặc Không; ý tưởng được xét theo đa số để nhóm có kết luận rõ ràng trước khi triển khai.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3, "textAlign": null}, "content": [{"text": "Quỹ chung minh bạch", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Ghi nhận các khoản đóng góp và chi tiêu, người thực hiện, mục đích và dự án liên quan. Nhóm theo dõi số dư và thống kê thu chi từ cùng một nơi thay vì đối chiếu nhiều bảng tính.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3, "textAlign": null}, "content": [{"text": "Dự án và tiến độ", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Theo dõi người phụ trách, ngân sách, chi phí thực tế và dòng thời gian cập nhật của từng dự án. Những thành viên làm việc khác lịch vẫn có thể xem tiến độ và tiếp nối công việc.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3, "textAlign": null}, "content": [{"text": "Tài nguyên và wiki nội bộ", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Quản lý domain, hosting, VPS và tài khoản trả phí cùng người giữ, giá và thời hạn. Lưu quy trình, ghi chú và quyết định bằng Markdown trong wiki để cả nhóm cùng cập nhật và tra cứu.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3, "textAlign": null}, "content": [{"text": "Poll, CofynAI và API", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Tạo bình chọn phương án trong ý tưởng. CofynAI hỗ trợ soạn poll, chấm điểm ý tưởng và trả lời bình luận. API dùng token riêng theo nhóm để đọc ý tưởng, dự án, thu chi và ghi cập nhật từ công cụ khác. Các khả năng AI và API phụ thuộc gói sử dụng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3, "textAlign": null}, "content": [{"text": "Nhật ký và kho lưu trữ", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Theo dõi các thay đổi đã xảy ra; nội dung đã xóa được đưa vào Kho lưu trữ để có thể khôi phục hoặc xử lý tiếp khi cần.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2, "textAlign": null}, "content": [{"text": "Cofyn phù hợp với ai?", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Nhóm co-founder từ 2–10 người:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " cùng xây sản phẩm và cần rõ ràng về đóng góp, chi phí và quyết định.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Nhóm side project:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " làm ngoài giờ, ít thời gian họp, cần ghi chú và cập nhật tiến độ tập trung.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Câu lạc bộ và đội dự án sinh viên:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " quản lý quỹ chung và đưa ra quyết định bằng biểu quyết.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2, "textAlign": null}, "content": [{"text": "Quy trình sử dụng", "type": "text"}]}, {"type": "orderedList", "attrs": {"type": null, "start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Đề xuất ý tưởng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " nêu vấn đề, cách làm và chi phí dự kiến.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Cả nhóm biểu quyết:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ghi nhận ý kiến để chốt hướng triển khai.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Chuyển thành dự án:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " giữ mô tả, ngân sách và bổ sung người phụ trách.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Triển khai và ghi chép:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " cập nhật tiến độ, thu chi, tài nguyên và tài liệu liên quan.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2, "textAlign": null}, "content": [{"text": "Trải nghiệm Cofyn trên web", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Cofyn hoạt động trên trình duyệt, có thể truy cập từ máy tính, iPad và điện thoại. Mỗi nhóm có không gian riêng; dữ liệu nhóm được chia sẻ cho thành viên trong nhóm, không phải một tài khoản chung với các sản phẩm Zukatek khác.", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Theo thông tin công khai của Cofyn, giai đoạn pilot miễn phí và không yêu cầu thẻ. Gói Free phục vụ nhu cầu nhóm cơ bản; AI và API được giới thiệu trong gói Premium. Điều kiện tính năng và gói sử dụng có thể thay đổi, hãy xem thông tin hiện hành trên website sản phẩm.", "type": "text"}]}, {"type": "paragraph", "attrs": {"textAlign": null}, "content": [{"text": "Tạo tài khoản Cofyn", "type": "text", "marks": [{"type": "link", "attrs": {"rel": "nofollow", "href": "https://cofyn.app/users/sign-up", "class": null, "title": null, "target": "_blank"}}]}, {"text": " để bắt đầu với nhóm của bạn, hoặc xem ", "type": "text"}, {"text": "hướng dẫn sử dụng Cofyn", "type": "text", "marks": [{"type": "link", "attrs": {"rel": "nofollow", "href": "https://cofyn.app/docs", "class": null, "title": null, "target": "_blank"}}]}, {"text": " trước khi trải nghiệm.", "type": "text"}]}]}, "cover_url": "/api/files/products/2bb5c174-fba2-416d-90ef-79b6c8113482/cover-a063c7a9-2acc-41ea-b193-71cbb2d9df30.png", "lifecycle": "launched", "platforms": ["web"], "categories": [], "cover_path": "products/2bb5c174-fba2-416d-90ef-79b6c8113482/cover-a063c7a9-2acc-41ea-b193-71cbb2d9df30.png", "created_at": "2026-10-18T13:28:54.969613+07:00", "highlights": ["Ideas → votes → projects", "Transparent shared team fund", "Team wiki and shared resources", "CofynAI and API by plan", "Vietnamese web interface"], "sort_order": 0, "tech_stack": [], "updated_at": "2026-10-18T18:31:16.383783+07:00", "demo_access": "Tạo tài khoản và nhóm riêng để trải nghiệm trên trình duyệt. Cofyn công bố miễn phí trong giai đoạn pilot, không cần thẻ. AI và API phụ thuộc gói sử dụng; xem điều kiện hiện hành tại cofyn.app.", "is_featured": false, "product_url": "https://cofyn.app/", "released_at": null, "published_at": "2026-10-18T13:30:44.039565+07:00", "demo_instructions": ["Tạo tài khoản Cofyn tại cofyn.app/users/sign-up.", "Tạo nhóm riêng và mời các thành viên cùng tham gia.", "Đăng ý tưởng, tổ chức biểu quyết và chuyển ý tưởng được duyệt thành dự án.", "Ghi thu chi, cập nhật tiến độ và lưu tài liệu; xem hướng dẫn tại cofyn.app/docs."]}', '2026-10-18 13:30:44.039565+07', '2026-10-18 18:31:16.400347+07')
